#include <iostream>
#include <sstream>
#include <string>
#include <iomanip>
#include <vector>
#include <format>

struct Lectura {
    std::string codigo;
    int cantidad;
    double medida;
};

std::string componer_resumen(const std::vector<Lectura>& lecturas) {
    std::string texto;
    int total = 0;
    double suma = 0.0;
    for (const auto& lectura : lecturas) {
        texto += std::format("[{:<6}]|[{:04d}]|[{:.2f}]\n", lectura.codigo,
            lectura.cantidad, lectura.medida);
        total += lectura.cantidad;
        suma += lectura.medida;
    }
    if (lecturas.empty()) {
        texto += "Données:0;Total:0;Sans moyenne";
    } else {
        double media = suma / static_cast<double>(lecturas.size());
        texto += std::format("Données:{};Total:{};Moyenne:{:.2f}", lecturas.size(), total, media);
    }
    return texto;
}

int main() {
    const std::vector<Lectura> lecturas{{"N", 4, 8.8125}, {"E", 9, 4.3125}};
    std::cout << componer_resumen(lecturas) << "\n";
    std::cout << std::format("{}", lecturas.at(0).medida * 16) << "\n";
    const std::vector<Lectura> vacias;
    std::cout << componer_resumen(vacias);
    return 0;
}

